import React, { useEffect, useState } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3000';

interface Machine {
  id: number;
  name: string;
  status: string;
  production: number;
  temperature: number;
}

interface Alert {
  id: number;
  machine: string;
  type: string;
  message: string;
}

function LandingPage({ onEnter }: { onEnter: () => void }) {
  const [visible, setVisible] = useState(false);
  const [count, setCount] = useState(0);

  useEffect(() => {
    setTimeout(() => setVisible(true), 100);
    const interval = setInterval(() => {
      setCount(prev => prev < 100 ? prev + 1 : 100);
    }, 20);
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ minHeight: '100vh', background: '#000913', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', fontFamily: 'Inter, sans-serif', position: 'relative', overflow: 'hidden' }}>

      {/* Grade animada */}
      <div style={{ position: 'absolute', inset: 0, backgroundImage: 'linear-gradient(rgba(0,200,255,0.04) 1px, transparent 1px), linear-gradient(90deg, rgba(0,200,255,0.04) 1px, transparent 1px)', backgroundSize: '60px 60px' }} />

      {/* Brilho central */}
      <div style={{ position: 'absolute', width: '800px', height: '800px', background: 'radial-gradient(circle, rgba(0,100,255,0.1) 0%, transparent 65%)', borderRadius: '50%', top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }} />

      {/* Linhas decorativas */}
      <div style={{ position: 'absolute', top: '20%', left: '5%', width: '150px', height: '1px', background: 'linear-gradient(90deg, transparent, rgba(0,150,255,0.5))' }} />
      <div style={{ position: 'absolute', top: '80%', right: '5%', width: '150px', height: '1px', background: 'linear-gradient(90deg, rgba(0,150,255,0.5), transparent)' }} />
      <div style={{ position: 'absolute', top: '30%', right: '8%', fontSize: '11px', color: 'rgba(0,150,255,0.3)', letterSpacing: '2px', writingMode: 'vertical-rl' }}>SYSTEM ACTIVE</div>
      <div style={{ position: 'absolute', top: '30%', left: '8%', fontSize: '11px', color: 'rgba(0,150,255,0.3)', letterSpacing: '2px', writingMode: 'vertical-rl' }}>INDUSTRY 4.0</div>

      {/* Conteúdo principal */}
      <div style={{ textAlign: 'center', zIndex: 1, opacity: visible ? 1 : 0, transform: visible ? 'translateY(0)' : 'translateY(40px)', transition: 'all 1.2s ease' }}>

        {/* Badge */}
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: '8px', background: 'rgba(0,150,255,0.08)', border: '1px solid rgba(0,150,255,0.25)', borderRadius: '20px', padding: '6px 16px', fontSize: '11px', color: '#00aaff', letterSpacing: '3px', textTransform: 'uppercase', marginBottom: '32px' }}>
          <div style={{ width: '6px', height: '6px', borderRadius: '50%', background: '#00ff88', boxShadow: '0 0 8px #00ff88' }} />
          Indústria 4.0 · Monitoramento em Tempo Real
        </div>

        {/* Título */}
        <h1 style={{ fontSize: '72px', fontWeight: '800', margin: '0 0 8px', background: 'linear-gradient(135deg, #ffffff 0%, #60a5fa 50%, #00aaff 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', lineHeight: 1.05, letterSpacing: '-2px' }}>
          SmartFactory
        </h1>
        <h2 style={{ fontSize: '72px', fontWeight: '800', margin: '0 0 32px', background: 'linear-gradient(135deg, #0088ff 0%, #00ddff 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', lineHeight: 1.05, letterSpacing: '-2px' }}>
          Dashboard
        </h2>

        <p style={{ color: '#475569', fontSize: '17px', maxWidth: '480px', lineHeight: 1.7, margin: '0 auto 48px' }}>
          Sistema de monitoramento industrial com dados em tempo real, alertas inteligentes e análise de produção.
        </p>

        {/* Barra de carregamento */}
        <div style={{ width: '300px', margin: '0 auto 32px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', color: '#475569', marginBottom: '6px', letterSpacing: '1px' }}>
            <span>INICIALIZANDO SISTEMA</span>
            <span style={{ color: '#00aaff' }}>{count}%</span>
          </div>
          <div style={{ height: '3px', background: 'rgba(255,255,255,0.05)', borderRadius: '2px' }}>
            <div style={{ width: `${count}%`, height: '100%', background: 'linear-gradient(90deg, #0055ff, #00ddff)', borderRadius: '2px', boxShadow: '0 0 10px rgba(0,150,255,0.6)', transition: 'width 0.1s linear' }} />
          </div>
        </div>

        {/* Botão */}
        <button onClick={onEnter} style={{ background: 'linear-gradient(135deg, #0044dd, #00aaff)', border: 'none', borderRadius: '50px', padding: '18px 56px', fontSize: '15px', fontWeight: '700', color: '#fff', cursor: 'pointer', letterSpacing: '2px', textTransform: 'uppercase', boxShadow: '0 0 40px rgba(0,150,255,0.3)', transition: 'all 0.3s ease' }}
          onMouseOver={e => { e.currentTarget.style.transform = 'scale(1.05)'; e.currentTarget.style.boxShadow = '0 0 60px rgba(0,150,255,0.5)'; }}
          onMouseOut={e => { e.currentTarget.style.transform = 'scale(1)'; e.currentTarget.style.boxShadow = '0 0 40px rgba(0,150,255,0.3)'; }}>
          Acessar Sistema →
        </button>

        {/* Stats */}
        <div style={{ display: 'flex', gap: '64px', justifyContent: 'center', marginTop: '64px' }}>
          {[
            { value: '5', label: 'Máquinas' },
            { value: '99%', label: 'Uptime' },
            { value: '24/7', label: 'Monitoramento' },
          ].map((s, i) => (
            <div key={i} style={{ textAlign: 'center' }}>
              <p style={{ fontSize: '30px', fontWeight: '800', color: '#00aaff', margin: '0 0 4px', textShadow: '0 0 20px rgba(0,150,255,0.5)' }}>{s.value}</p>
              <p style={{ fontSize: '11px', color: '#334155', margin: 0, letterSpacing: '2px', textTransform: 'uppercase' }}>{s.label}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function Dashboard({ onBack }: { onBack: () => void }) {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [filter, setFilter] = useState<string>('todos');
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    axios.get(`${API_URL}/api/machines`).then(res => setMachines(res.data));
    axios.get(`${API_URL}/api/alerts`).then(res => setAlerts(res.data));
    const clock = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(clock);
  }, []);

  const refresh = () => {
    axios.get(`${API_URL}/api/machines`).then(res => setMachines(res.data));
    axios.get(`${API_URL}/api/alerts`).then(res => setAlerts(res.data));
  };

  const filtered = filter === 'todos' ? machines : machines.filter(m => m.status === filter);
  const operando = machines.filter(m => m.status === 'operando').length;
  const falha = machines.filter(m => m.status === 'falha').length;
  const manutencao = machines.filter(m => m.status === 'manutenção').length;
  const mediaProducao = machines.length > 0 ? Math.round(machines.reduce((a, m) => a + m.production, 0) / machines.length) : 0;

  const statusColor = (status: string) => {
    if (status === 'operando') return '#00ff88';
    if (status === 'falha') return '#ff3355';
    return '#ffaa00';
  };

  const tempColor = (temp: number) => temp >= 60 ? '#ff3355' : temp >= 45 ? '#ffaa00' : '#00aaff';

  return (
    <div style={{ minHeight: '100vh', background: '#000913', color: '#e2e8f0', fontFamily: 'Inter, sans-serif', padding: '20px', backgroundImage: 'linear-gradient(rgba(0,200,255,0.015) 1px, transparent 1px), linear-gradient(90deg, rgba(0,200,255,0.015) 1px, transparent 1px)', backgroundSize: '60px 60px' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', background: 'rgba(0,150,255,0.04)', border: '1px solid rgba(0,150,255,0.12)', borderRadius: '12px', padding: '14px 20px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <button onClick={onBack} style={{ background: 'rgba(0,150,255,0.1)', border: '1px solid rgba(0,150,255,0.2)', borderRadius: '8px', padding: '6px 12px', color: '#00aaff', cursor: 'pointer', fontSize: '12px' }}>← Voltar</button>
          <div>
            <h1 style={{ fontSize: '18px', fontWeight: '700', color: '#00aaff', margin: 0, letterSpacing: '1px' }}>⚙️ SMARTFACTORY DASHBOARD</h1>
            <p style={{ color: '#334155', margin: 0, fontSize: '11px', letterSpacing: '1px' }}>MONITORAMENTO INDUSTRIAL EM TEMPO REAL</p>
          </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
          <span style={{ color: '#334155', fontSize: '12px', fontFamily: 'monospace' }}>{time.toLocaleTimeString()}</span>
          <button onClick={refresh} style={{ background: 'rgba(0,255,136,0.1)', border: '1px solid rgba(0,255,136,0.2)', borderRadius: '8px', padding: '6px 14px', color: '#00ff88', cursor: 'pointer', fontSize: '12px', letterSpacing: '1px' }}>↻ ATUALIZAR</button>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <div style={{ width: '7px', height: '7px', borderRadius: '50%', background: '#00ff88', boxShadow: '0 0 8px #00ff88' }} />
            <span style={{ color: '#00ff88', fontSize: '11px', letterSpacing: '1px' }}>ONLINE</span>
          </div>
        </div>
      </div>

      {/* Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '14px', marginBottom: '20px' }}>
        {[
          { label: 'OPERANDO', value: operando, color: '#00ff88', icon: '✓' },
          { label: 'EM FALHA', value: falha, color: '#ff3355', icon: '✗' },
          { label: 'MANUTENÇÃO', value: manutencao, color: '#ffaa00', icon: '⚠' },
          { label: 'PRODUÇÃO MÉDIA', value: `${mediaProducao}%`, color: '#00aaff', icon: '◈' },
        ].map((card, i) => (
          <div key={i} style={{ background: 'rgba(0,0,0,0.4)', border: `1px solid ${card.color}22`, borderRadius: '12px', padding: '18px 20px', position: 'relative', overflow: 'hidden', cursor: 'pointer' }}
            onMouseOver={e => e.currentTarget.style.border = `1px solid ${card.color}55`}
            onMouseOut={e => e.currentTarget.style.border = `1px solid ${card.color}22`}>
            <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '2px', background: `linear-gradient(90deg, transparent, ${card.color}, transparent)` }} />
            <div style={{ position: 'absolute', top: '16px', right: '16px', fontSize: '20px', color: `${card.color}33` }}>{card.icon}</div>
            <p style={{ color: '#334155', fontSize: '10px', margin: '0 0 10px', letterSpacing: '2px' }}>{card.label}</p>
            <p style={{ fontSize: '38px', fontWeight: '800', color: card.color, margin: 0, textShadow: `0 0 20px ${card.color}44`, lineHeight: 1 }}>{card.value}</p>
          </div>
        ))}
      </div>

      {/* Filtros */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        {['todos', 'operando', 'falha', 'manutenção'].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{ background: filter === f ? 'rgba(0,150,255,0.2)' : 'rgba(0,0,0,0.3)', border: `1px solid ${filter === f ? 'rgba(0,150,255,0.5)' : 'rgba(255,255,255,0.06)'}`, borderRadius: '8px', padding: '6px 16px', color: filter === f ? '#00aaff' : '#475569', cursor: 'pointer', fontSize: '11px', letterSpacing: '1px', textTransform: 'uppercase', transition: 'all 0.2s' }}>
            {f}
          </button>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '16px' }}>

        {/* Máquinas */}
        <div style={{ background: 'rgba(0,0,0,0.4)', border: '1px solid rgba(0,150,255,0.1)', borderRadius: '12px', padding: '18px' }}>
          <h2 style={{ fontSize: '11px', fontWeight: '700', margin: '0 0 14px', color: '#00aaff', letterSpacing: '2px' }}>🏭 MÁQUINAS</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {filtered.map(m => (
              <div key={m.id} style={{ background: `${statusColor(m.status)}06`, border: `1px solid ${statusColor(m.status)}18`, borderRadius: '8px', padding: '10px 14px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', transition: 'all 0.2s' }}
                onMouseOver={e => e.currentTarget.style.background = `${statusColor(m.status)}10`}
                onMouseOut={e => e.currentTarget.style.background = `${statusColor(m.status)}06`}>
                <div>
                  <p style={{ margin: '0 0 3px', fontWeight: '600', fontSize: '13px', color: '#cbd5e1' }}>{m.name}</p>
                  <p style={{ margin: 0, fontSize: '11px', color: '#334155' }}>
                    <span style={{ color: tempColor(m.temperature) }}>🌡 {m.temperature}°C</span>
                    <span style={{ margin: '0 6px', color: '#1e293b' }}>|</span>
                    <span>📦 {m.production}%</span>
                  </p>
                </div>
                <span style={{ background: `${statusColor(m.status)}15`, color: statusColor(m.status), fontSize: '10px', fontWeight: '700', padding: '3px 10px', borderRadius: '20px', border: `1px solid ${statusColor(m.status)}33`, letterSpacing: '1px', textTransform: 'uppercase' }}>
                  {m.status}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Produção */}
        <div style={{ background: 'rgba(0,0,0,0.4)', border: '1px solid rgba(0,150,255,0.1)', borderRadius: '12px', padding: '18px' }}>
          <h2 style={{ fontSize: '11px', fontWeight: '700', margin: '0 0 14px', color: '#00aaff', letterSpacing: '2px' }}>📊 PRODUÇÃO POR MÁQUINA</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            {machines.map(m => (
              <div key={m.id}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', color: '#334155', marginBottom: '5px' }}>
                  <span style={{ color: '#64748b' }}>{m.name}</span>
                  <span style={{ color: statusColor(m.status), fontWeight: '700' }}>{m.production}%</span>
                </div>
                <div style={{ height: '5px', background: 'rgba(255,255,255,0.04)', borderRadius: '3px', position: 'relative' }}>
                  <div style={{ width: `${m.production}%`, height: '100%', background: `linear-gradient(90deg, ${statusColor(m.status)}66, ${statusColor(m.status)})`, borderRadius: '3px', boxShadow: `0 0 8px ${statusColor(m.status)}55`, transition: 'width 1s ease' }} />
                </div>
              </div>
            ))}
          </div>

          {/* Mini stats */}
          <div style={{ marginTop: '24px', paddingTop: '16px', borderTop: '1px solid rgba(255,255,255,0.04)', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
            <div style={{ background: 'rgba(0,255,136,0.05)', border: '1px solid rgba(0,255,136,0.1)', borderRadius: '8px', padding: '10px' }}>
              <p style={{ margin: '0 0 4px', fontSize: '10px', color: '#334155', letterSpacing: '1px' }}>MAIOR PRODUÇÃO</p>
              <p style={{ margin: 0, fontSize: '14px', fontWeight: '700', color: '#00ff88' }}>
                {machines.length > 0 ? Math.max(...machines.map(m => m.production)) : 0}%
              </p>
            </div>
            <div style={{ background: 'rgba(255,51,85,0.05)', border: '1px solid rgba(255,51,85,0.1)', borderRadius: '8px', padding: '10px' }}>
              <p style={{ margin: '0 0 4px', fontSize: '10px', color: '#334155', letterSpacing: '1px' }}>MENOR PRODUÇÃO</p>
              <p style={{ margin: 0, fontSize: '14px', fontWeight: '700', color: '#ff3355' }}>
                {machines.length > 0 ? Math.min(...machines.map(m => m.production)) : 0}%
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Alertas */}
      <div style={{ background: 'rgba(0,0,0,0.4)', border: '1px solid rgba(0,150,255,0.1)', borderRadius: '12px', padding: '18px' }}>
        <h2 style={{ fontSize: '11px', fontWeight: '700', margin: '0 0 14px', color: '#00aaff', letterSpacing: '2px' }}>🚨 ALERTAS RECENTES</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {alerts.map(a => (
            <div key={a.id} style={{ background: a.type === 'critico' ? 'rgba(255,51,85,0.06)' : a.type === 'aviso' ? 'rgba(255,170,0,0.06)' : 'rgba(255,255,255,0.02)', border: `1px solid ${a.type === 'critico' ? 'rgba(255,51,85,0.2)' : a.type === 'aviso' ? 'rgba(255,170,0,0.2)' : 'rgba(255,255,255,0.05)'}`, borderRadius: '8px', padding: '10px 14px', display: 'flex', gap: '12px', alignItems: 'center' }}>
              <div style={{ width: '7px', height: '7px', borderRadius: '50%', background: a.type === 'critico' ? '#ff3355' : a.type === 'aviso' ? '#ffaa00' : '#334155', boxShadow: a.type === 'critico' ? '0 0 8px #ff3355' : a.type === 'aviso' ? '0 0 8px #ffaa00' : 'none', flexShrink: 0 }} />
              <div style={{ flex: 1 }}>
                <p style={{ margin: '0 0 2px', fontWeight: '700', fontSize: '12px', color: a.type === 'critico' ? '#ff3355' : a.type === 'aviso' ? '#ffaa00' : '#475569', letterSpacing: '0.5px' }}>{a.machine}</p>
                <p style={{ margin: 0, fontSize: '11px', color: '#334155' }}>{a.message}</p>
              </div>
              <span style={{ fontSize: '10px', color: '#1e293b', letterSpacing: '1px' }}>{a.type?.toUpperCase()}</span>
            </div>
          ))}
        </div>
      </div>

    </div>
  );
}

export default function App() {
  const [page, setPage] = useState<'landing' | 'dashboard'>('landing');
  return page === 'landing'
    ? <LandingPage onEnter={() => setPage('dashboard')} />
    : <Dashboard onBack={() => setPage('landing')} />;
}
